package com.k8s.cli.cache

import java.security.MessageDigest
import java.nio.file.{Files, Paths, Path}
import java.nio.charset.StandardCharsets
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

object CacheConfig {
  val CACHE_DIR: String = sys.env.getOrElse("CACHE_DIR", "/tmp/k8s-cli-cache")
  val CACHE_TTL_MS: Long = sys.env.getOrElse("CACHE_TTL_MS", "300000").toLong
  val NAMESPACE: String = sys.env.getOrElse("K8S_NAMESPACE", "default")
  val SERVICE_ACCOUNT: String = sys.env.getOrElse("K8S_SA", "cli-runner")
}

case class CacheEntry(content: Array[Byte], timestamp: Long, source: String)

trait CacheKeyDerivation {
  def deriveKey(namespace: String, resource: String, identity: String): String
}

class HMACKeyDerivation extends CacheKeyDerivation {
  private val secret: Array[Byte] = sys.env.getOrElse("CACHE_SECRET", "k8s-cli-default-hmac-key").getBytes(StandardCharsets.UTF_8)

  override def deriveKey(namespace: String, resource: String, identity: String): String = {
    val md = MessageDigest.getInstance("SHA-256")
    md.update(secret)
    md.update(namespace.getBytes(StandardCharsets.UTF_8))
    md.update(resource.getBytes(StandardCharsets.UTF_8))
    md.update(identity.getBytes(StandardCharsets.UTF_8))
    bytesToHex(md.digest())
  }

  private def bytesToHex(bytes: Array[Byte]): String =
    bytes.map("%02x".format(_)).mkString
}

class NamespacedKeyDerivation extends CacheKeyDerivation {
  override def deriveKey(namespace: String, resource: String, identity: String): String = {
    val md = MessageDigest.getInstance("SHA-256")
    val separator = "\u0000"
    val input = s"${namespace}${separator}${resource}${separator}${identity}"
    bytesToHex(md.digest(input.getBytes(StandardCharsets.UTF_8)))
  }

  private def bytesToHex(bytes: Array[Byte]): String =
    bytes.map("%02x".format(_)).mkString
}

class ResourceCache(keyDerivation: CacheKeyDerivation) {
  private val memCache: TrieMap[String, CacheEntry] = TrieMap.empty

  def get(namespace: String, resource: String, identity: String): Option[CacheEntry] = {
    val key = keyDerivation.deriveKey(namespace, resource, identity)
    memCache.get(key).flatMap { entry =>
      if (isValid(entry)) Some(entry)
      else { memCache.remove(key); None }
    }.orElse(loadFromDisk(key))
  }

  def put(namespace: String, resource: String, identity: String, content: Array[Byte], source: String): Unit = {
    val key = keyDerivation.deriveKey(namespace, resource, identity)
    val entry = CacheEntry(content, System.currentTimeMillis(), source)
    memCache.put(key, entry)
    persistToDisk(key, entry)
  }

  private def isValid(entry: CacheEntry): Boolean = {
    val age = System.currentTimeMillis() - entry.timestamp
    age < CacheConfig.CACHE_TTL_MS
  }

  private def loadFromDisk(key: String): Option[CacheEntry] = {
    val path = Paths.get(CacheConfig.CACHE_DIR, key)
    Try(Files.readAllBytes(path)) match {
      case Success(bytes) =>
        val entry = CacheEntry(bytes, Files.getLastModifiedTime(path).toMillis, "disk")
        if (isValid(entry)) { memCache.put(key, entry); Some(entry) }
        else { Files.deleteIfExists(path); None }
      case Failure(_) => None
    }
  }

  private def persistToDisk(key: String, entry: CacheEntry): Unit = {
    val dir = Paths.get(CacheConfig.CACHE_DIR)
    if (!Files.exists(dir)) Files.createDirectories(dir)
    Files.write(Paths.get(CacheConfig.CACHE_DIR, key), entry.content)
  }
}

object KubeResourceFetcher {
  def fetchResource(namespace: String, resourceType: String, name: String): Array[Byte] = {
    // Simulates kubectl get <resourceType> <name> -n <namespace> -o json
    val cmd = Seq("kubectl", "get", resourceType, name, "-n", namespace, "-o", "json")
    val process = new ProcessBuilder(cmd: _*).start()
    val output = process.getInputStream.readAllBytes()
    process.waitFor()
    output
  }
}

class CLIHandler(cache: ResourceCache) {
  def handleRequest(namespace: String, resourceType: String, name: String, serviceAccount: String): Array[Byte] = {
    val identity = resolveIdentity(serviceAccount, namespace)
    cache.get(namespace, s"$resourceType/$name", identity) match {
      case Some(entry) => entry.content
      case None =>
        val content = KubeResourceFetcher.fetchResource(namespace, resourceType, name)
        cache.put(namespace, s"$resourceType/$name", identity, content, "api")
        content
    }
  }

  private def resolveIdentity(serviceAccount: String, namespace: String): String = {
    s"system:serviceaccount:${namespace}:${serviceAccount}"
  }
}

object Main extends App {
  val keyDerivation = selectKeyDerivation()
  val cache = new ResourceCache(keyDerivation)
  val handler = new CLIHandler(cache)

  val namespace = args.lift(0).getOrElse(CacheConfig.NAMESPACE)
  val resourceType = args.lift(1).getOrElse("configmap")
  val name = args.lift(2).getOrElse("app-config")

  val result = handler.handleRequest(namespace, resourceType, name, CacheConfig.SERVICE_ACCOUNT)
  println(new String(result, StandardCharsets.UTF_8))

  private def selectKeyDerivation(): CacheKeyDerivation = {
    sys.env.getOrElse("KEY_DERIVATION", "namespaced") match {
      case "hmac" => new HMACKeyDerivation()
      case _ => new NamespacedKeyDerivation()
    }
  }
}
